// CrewBus M4 pair-QR window — static ES module wired to the VENDORED
// runtime (src/vendor/runtime/, generated by `npm run vendor` from
// packages/client-runtime — never import out of root).
//
// Fragment-secret hygiene (packages/contracts/pairing.json, enforced by the
// runtime parsePairUrl imported below):
//   1. The pairing secret MUST come from the #fragment. Any secret-looking
//      query value (or secret-named query key) is REJECTED outright.
//   2. The full URL is NEVER logged, persisted, or embedded anywhere except
//      the in-memory QR render. Status lines print the env id only, with the
//      fragment stripped.
//   3. One-time link per device: Clear wipes the textarea + QR on demand;
//      the window holds no copy afterwards.
//
// Runs as plain static JS: browser globals only, `node --check` clean.

'use strict';

import { parsePairUrl } from './vendor/runtime/index.js';
import { renderQrSvg } from './vendor/qrcode.js';

var box = document.getElementById('pair-url');
var qr = document.getElementById('qr');
var qrWrap = document.getElementById('qr-wrap') || (qr ? qr.parentElement : null);
var msg = document.getElementById('msg');
var renderBtn = document.getElementById('pair-render');
var clearBtn = document.getElementById('pair-clear');

function say(t, isErr) {
  if (!msg) return;
  msg.textContent = t;
  msg.className = isErr ? 'warn' : 'ok';
}

function qrThemeColors() {
  var theme = null;
  try { theme = localStorage.getItem('crewbus-desktop-theme'); } catch (_) {}
  if (theme !== 'light' && theme !== 'dark') {
    try { theme = document.documentElement.getAttribute('data-theme'); } catch (_) {}
  }
  if (theme !== 'light' && theme !== 'dark') {
    try { theme = (window.matchMedia && window.matchMedia('(prefers-color-scheme:dark)').matches) ? 'dark' : 'light'; }
    catch (_) { theme = 'light'; }
  }
  if (theme === 'dark') return { dark: '#e3e9ee', light: '#182028' };
  return { dark: '#14201a', light: '#ffffff' };
}

// Pair window follows the desktop shell theme (same crewbus-desktop-theme
// key, written by the shell toggle): no toggle here, just honor stored /
// system theme so the QR contrast matches the shell chrome.
try {
  var __t = null;
  try { __t = localStorage.getItem('crewbus-desktop-theme'); } catch (_) {}
  if (__t !== 'light' && __t !== 'dark') {
    try {
      var __mq = window.matchMedia && window.matchMedia('(prefers-color-scheme:dark)');
      if (__mq && __mq.addEventListener) {
        __mq.addEventListener('change', function () {
          var cur = null;
          try { cur = localStorage.getItem('crewbus-desktop-theme'); } catch (_) {}
          if (cur !== 'light' && cur !== 'dark') {
            try { document.documentElement.removeAttribute('data-theme'); } catch (_) {}
          }
        });
      }
    } catch (_) {}
  }
} catch (_) {}

function parsePairUrlSpike(raw) {
  var parsed = parsePairUrl(String(raw == null ? '' : raw).trim());
  return { env: parsed.env || '(unknown env)', pairToken: parsed.pairToken };
}

function describeForDisplay(u) {
  return String(u).split('#')[0];
}

function clearAll() {
  if (box) box.value = '';
  if (qrWrap) qrWrap.innerHTML = '<div id="qr" aria-label="pairing QR">QR code will appear here after rendering</div>';
  qr = document.getElementById('qr');
  say('');
}

if (renderBtn) {
  renderBtn.addEventListener('click', function () {
    var raw = box ? box.value : '';
    if (!raw.trim()) {
      say('paste a pair URL first', true);
      return;
    }
    var parsed;
    try {
      parsed = parsePairUrlSpike(raw);
    } catch (e) {
      say('rejected: ' + String((e && e.message) || e), true);
      return;
    }

    try {
      var svg = renderQrSvg(raw.trim(), {
        width: 200,
        margin: 1,
        color: qrThemeColors(),
      });
      if (qrWrap) qrWrap.innerHTML = svg;
      say('QR code ready for ' + describeForDisplay(raw) + ' — scan with CrewBus Mobile.');
    } catch (err) {
      if (qr) qr.textContent = 'QR for ' + parsed.env + ' (' + parsed.pairToken.length + '-char secret)';
      say('QR render fallback: ' + String(err.message || err), true);
    }
  });
}

if (clearBtn) {
  clearBtn.addEventListener('click', clearAll);
}

// Plug-and-play auto-mint: when the shell passes ?dashboard=<sidecar-origin>
// (open_pair_window command), mint a one-time pair URL via POST
// /api/pair-qr on open and render the QR immediately — no terminal, no paste.
// Loopback-validated (the pair window CSP only allows loopback fetches
// anyway). Manual paste stays as the advanced/CLI fallback.
function dashboardParam() {
  try {
    return new URLSearchParams(window.location.search).get('dashboard') || '';
  } catch (_) { return ''; }
}

async function autoMint(base) {
  say('minting a one-time pairing link…');
  try {
    var r = await fetch(base.replace(/\/+$/, '') + '/api/pair-qr', { method: 'POST' });
    var j = null;
    try { j = await r.json(); } catch (_) {}
    if (!r.ok || !j || !j.ok || !j.pairUrl) {
      say('auto-mint failed (' + (j && j.error ? j.error : ('HTTP ' + r.status)) + ') — paste a pair URL manually', true);
      return;
    }
    if (box) box.value = j.pairUrl;
    // Reuse the shared render path (parse + hygiene + QR).
    if (renderBtn) renderBtn.click();
    var exp = j.expiresAt ? new Date(j.expiresAt) : null;
    say('QR ready — scan with CrewBus Mobile.' + (exp ? ' Link expires ' + exp.toLocaleTimeString() + ' (single-use).' : ''));
  } catch (e) {
    say('auto-mint failed: ' + String((e && e.message) || e) + ' — paste a pair URL manually', true);
  }
}

(function bootAutoMint() {
  var base = dashboardParam();
  if (!base) return; // manual-only mode (no ?dashboard= — e.g. dev tab)
  // Validate loopback: the pair window must only ever fetch the local
  // sidecar (mirrors the shell's isLoopbackUrl gate; CSP enforces it too).
  var u = null;
  try { u = new URL(base); } catch (_) { return; }
  var host = u.hostname;
  var loop = host === '127.0.0.1' || host === 'localhost' || host === '[::1]' || host === '::1';
  if ((u.protocol !== 'http:' && u.protocol !== 'https:') || !loop) return;
  autoMint(base);
})();
